export interface UserAppRoleDefinition {
    domain : string
    site : string
    appId: string
    appType: string
    appRoles: string
}

export function getAppRoleDefinitionsFromRole(role: UserRole): UserAppRoleDefinition[] {

    let appsInfo: UserAppRoleDefinition[] = []
    if (role.apps) {
        const apps = role.apps.split(";")
        for (const a of apps) {
            const appRecord = a.split(":")
            let appDef = {
                domain: role.domain,
                site: role.site,
                appType: (appRecord.length > 1) ? appRecord[1] : "*",
                appId: appRecord[0],
                appRoles: (appRecord.length > 2) ? appRecord[2] : "*",
            }

            appsInfo.push(appDef);
        }
    }

    return appsInfo
}


export function GetFirstRoleInApp(user: Partial<User>, domain: string, site: string, appType: string, appId: string) : string {
    if (user.roles) {
        for (const r of user.roles) {

            if (r.domain != "*" && r.domain != domain) {
                continue
            }

            if (r.site != "*" && r.site != site && site != "*" && site != "star") {
                continue
            }

            let appsInRole = getAppRoleDefinitionsFromRole(r)
            for (const ar of appsInRole) {

                if (ar.appType != "*" && ar.appType != appType) {
                    continue
                }

                if (ar.appId != "*" && ar.appId != appId) {
                    continue
                }

                if (ar.appRoles == "*") {
                    return ar.appRoles
                }
                let appRolesArray = ar.appRoles.split(",")
                return appRolesArray[0]
            }
        }
    }
    return ""
}

export function HasRole(user: Partial<User>, domain: string, site: string, appType: string, appId: string, ...appRoles: string[]) : boolean {
    if (user.roles) {
        for (const r of user.roles) {

            if (r.domain != "*" && r.domain != domain) {
                continue
            }

            if (r.site != "*" && r.site != site && site != "*" && site != "star") {
                continue
            }

            let appsInRole = getAppRoleDefinitionsFromRole(r)
            for (const ar of appsInRole) {

                if (ar.appType != "*" && ar.appType != appType) {
                    continue
                }

                if (ar.appId != "*" && ar.appId != appId) {
                    continue
                }

                // roles have been specified and the user doesn't have a role wildcard...
                if (appRoles && appRoles.length > 0 && ar.appRoles != "*") {
                    for (const r of appRoles) {
                        let appRolesArray = ar.appRoles.split(",")
                        for (const ur of appRolesArray) {
                            if (r == ur) {
                                return true
                            }
                        }
                    }
                    return false
                }

                return true
            }
        }
    }
    return false
}

export function HasAnyRoleInSite(user: Partial<User>, domain: string, site: string, appType: string) : boolean {
    if (user.roles) {
        for (const r of user.roles) {

            if (r.domain != "*" && r.domain != domain) {
                continue
            }

            if (r.site != "*" && r.site != site && site != "*" && site != "star") {
                continue
            }

            let appsInRole = getAppRoleDefinitionsFromRole(r)
            for (const ar of appsInRole) {

                if (ar.appType != "*" && ar.appType != appType) {
                    continue
                }

                return true
            }
        }
    }
    return false
}

